package net.officefloor.hq.app.dashboard;

import java.time.LocalDate;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {

    private final DashboardService service;

    public DashboardController(DashboardService service) {
        this.service = service;
    }

    @GetMapping
    public DashboardResponse summary() {
        return service.summary();
    }

    /** The tax charged on invoices issued on or between the given dates. */
    @GetMapping("/tax-summary")
    public TaxSummaryResponse taxSummary(@RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.taxSummary(from, to);
    }
}
package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.util.List;

/**
 * Summary figures for the dashboard, with the clients who owe the most. What is outstanding is
 * given per currency, since amounts in different currencies cannot be added together. What is overdue
 * (left to pay on overdue invoices plus the late fees and instalment interest they have built up) is one total in
 * the home currency, and is also split by how many days overdue each invoice is.
 * What is outstanding is also given as one grand total in the home currency, each invoice converted at the
 * exchange rate from its own issue date.
 */
public record DashboardResponse(long clients, long projects, List<CurrencyTotal> outstanding,
        BigDecimal outstandingHome, long overdue,
        String homeCurrency, BigDecimal overdueAmount, OverdueBuckets overdueBuckets, List<TopClient> topClients) {

    /** What is still owed in one currency. */
    public record CurrencyTotal(String currency, BigDecimal amount) {
    }

    /** What is overdue, in the home currency, by how many days past due: up to 30, 31 to 60, and more than 60. */
    public record OverdueBuckets(BigDecimal days0To30, BigDecimal days31To60, BigDecimal days60Plus) {
    }

    /** A client and what they still owe, in their currency and converted into the home currency. */
    public record TopClient(Long id, String name, String currency, BigDecimal outstanding, BigDecimal outstandingHome) {
    }
}
package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.client.ClientService;
import net.officefloor.hq.app.creditnote.CreditNoteRepository;
import net.officefloor.hq.app.currency.Currency;
import net.officefloor.hq.app.fx.FxRateService;
import net.officefloor.hq.app.instalment.Instalment;
import net.officefloor.hq.app.instalment.InstalmentRepository;
import net.officefloor.hq.app.invoice.Invoice;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.ProjectRepository;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class DashboardService {

    private final ClientRepository clients;
    private final ProjectRepository projects;
    private final InvoiceRepository invoices;
    private final ClientService clientService;
    private final PaymentRepository payments;
    private final CreditNoteRepository creditNotes;
    private final SettingsService settings;
    private final FxRateService fxRates;
    private final InstalmentRepository instalments;
    private final Clock clock;

    /** How many of the biggest debtors the dashboard lists. */
    static final int TOP_CLIENTS = 5;

    public DashboardService(ClientRepository clients, ProjectRepository projects, InvoiceRepository invoices,
            ClientService clientService, PaymentRepository payments, CreditNoteRepository creditNotes,
            SettingsService settings, FxRateService fxRates, InstalmentRepository instalments, Clock clock) {
        this.clients = clients;
        this.projects = projects;
        this.invoices = invoices;
        this.clientService = clientService;
        this.payments = payments;
        this.creditNotes = creditNotes;
        this.settings = settings;
        this.fxRates = fxRates;
        this.instalments = instalments;
        this.clock = clock;
    }

    /**
     * Counts of clients and projects, and the total still owed in each currency (what is left to pay
     * on sent invoices that are not yet fully paid; a currency with written-off invoices is listed even when nothing is owed), plus how many of those sent invoices are past their due date and
     * what is overdue on them (in total and split by how many days overdue each invoice is), what is outstanding as one grand total in the home currency (see {@link #inHome}), and the top clients ranked by what they owe converted into the home currency (a client none of whose debt can be converted is left out).
     */
    @Transactional(readOnly = true)
    public DashboardResponse summary() {
        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
        Map<String, BigDecimal> owed = new TreeMap<>(Currency.ORDER);
        // A currency whose debts were written off stays listed, showing nothing owed, so the write-off is visible.
        clients.findAllById(invoices.sumAmountByStatusInPerClient(List.of(InvoiceStatus.WRITTEN_OFF)).stream()
                .map(InvoiceRepository.ClientTotal::getClientId).toList())
                .forEach(c -> owed.put(c.getCurrency(), BigDecimal.ZERO));
        owed.putAll(clientService.outstandingByCurrency());
        List<DashboardResponse.CurrencyTotal> outstanding = owed.entrySet().stream()
                .map(e -> new DashboardResponse.CurrencyTotal(e.getKey(), e.getValue().setScale(2, RoundingMode.HALF_UP)))
                .toList();
        LocalDate today = LocalDate.now(clock);
        long overdue = invoices.countByStatusInAndDueDateBefore(owing, today);
        String home = settings.homeCurrency();
        Map<Invoice, BigDecimal> owedInHome = inHome(invoices.findByStatusInWithClient(owing), home, today, false);
        BigDecimal outstandingHome = sum(owedInHome);
        Map<Invoice, BigDecimal> overdueInHome = inHome(invoices.findByStatusInAndDueDateBefore(owing, today), home, today, true);
        BigDecimal overdueAmount = sum(overdueInHome);
        DashboardResponse.OverdueBuckets overdueBuckets = buckets(overdueInHome, today);
        Map<Long, BigDecimal> clientsInHome = new HashMap<>();
        owedInHome.forEach((invoice, amount) -> clientsInHome.merge(invoice.getProject().getClient().getId(), amount,
                BigDecimal::add));
        List<DashboardResponse.TopClient> top = clientService.topByOutstanding(TOP_CLIENTS, clientsInHome).stream()
                .map(c -> new DashboardResponse.TopClient(c.id(), c.name(), c.currency(), c.outstanding(),
                        clientsInHome.get(c.id()).setScale(2, RoundingMode.HALF_UP)))
                .toList();
        return new DashboardResponse(clients.count(), projects.count(), outstanding, outstandingHome, overdue, home, overdueAmount,
                overdueBuckets, top);
    }

    /**
     * Splits what is overdue by how many days past its due date each invoice is: up to 30 days, 31 to 60 days,
     * and more than 60 days.
     */
    private static DashboardResponse.OverdueBuckets buckets(Map<Invoice, BigDecimal> overdueInHome, LocalDate today) {
        BigDecimal upTo30 = BigDecimal.ZERO;
        BigDecimal days31To60 = BigDecimal.ZERO;
        BigDecimal days60Plus = BigDecimal.ZERO;
        for (Map.Entry<Invoice, BigDecimal> e : overdueInHome.entrySet()) {
            long days = ChronoUnit.DAYS.between(e.getKey().getDueDate(), today);
            if (days > 60) {
                days60Plus = days60Plus.add(e.getValue());
            } else if (days > 30) {
                days31To60 = days31To60.add(e.getValue());
            } else {
                upTo30 = upTo30.add(e.getValue());
            }
        }
        return new DashboardResponse.OverdueBuckets(upTo30.setScale(2, RoundingMode.HALF_UP),
                days31To60.setScale(2, RoundingMode.HALF_UP), days60Plus.setScale(2, RoundingMode.HALF_UP));
    }

    private static BigDecimal sum(Map<Invoice, BigDecimal> amounts) {
        return amounts.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * What is left to pay on each of the invoices, in the home currency, with the late fee and the interest on late
     * instalments each has built up by today when asked for (as for what is overdue). A foreign invoice converts at
     * the exchange rate from its issue date; one whose currency has no rate by then cannot be converted and is left out.
     */
    private Map<Invoice, BigDecimal> inHome(List<Invoice> found, String home, LocalDate today, boolean withCharges) {
        Map<Invoice, BigDecimal> amounts = new LinkedHashMap<>();
        if (found.isEmpty()) {
            return amounts;
        }
        List<Long> ids = found.stream().map(Invoice::getId).toList();
        Map<Long, BigDecimal> paid = payments.sumAmountByInvoiceIds(ids).stream()
                .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                        PaymentRepository.InvoicePaidTotal::getPaid));
        Map<Long, BigDecimal> credited = creditNotes.sumAmountByInvoiceIds(ids).stream()
                .collect(Collectors.toMap(CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
                        CreditNoteRepository.InvoiceCreditedTotal::getCredited));
        Map<Long, List<Instalment>> scheduled = withCharges
                ? instalments.findByInvoiceIdIn(ids).stream().collect(Collectors.groupingBy(Instalment::getInvoiceId))
                : Map.of();
        for (Invoice invoice : found) {
            BigDecimal due = invoice.amountDue(paid.getOrDefault(invoice.getId(), BigDecimal.ZERO),
                    credited.getOrDefault(invoice.getId(), BigDecimal.ZERO));
            if (withCharges) {
                due = due.add(invoice.lateFee(invoice.getStatus(), today))
                        .add(interest(invoice, scheduled.getOrDefault(invoice.getId(), List.of()), today));
            }
            String currency = invoice.getProject().getClient().getCurrency();
            BigDecimal inHome = currency.equals(home) ? due
                    : fxRates.toHome(currency, invoice.getIssuedDate(), due).orElse(null);
            if (inHome != null) {
                amounts.put(invoice, inHome);
            }
        }
        return amounts;
    }

    /** The interest built up by today on an invoice's instalments still unpaid past their due dates. */
    private static BigDecimal interest(Invoice invoice, List<Instalment> scheduled, LocalDate today) {
        BigDecimal total = BigDecimal.ZERO;
        for (Instalment instalment : scheduled) {
            if (instalment.isPaid()) {
                continue;
            }
            long daysLate = Math.max(0, ChronoUnit.DAYS.between(instalment.getDueDate(), today));
            total = total.add(invoice.getInstalmentInterestPerDay().multiply(BigDecimal.valueOf(daysLate))
                    .setScale(2, RoundingMode.HALF_UP));
        }
        return total;
    }

    /**
     * The tax charged over a period, in the home currency: the sales tax and levy on every invoice issued on or
     * between the given dates that was actually charged (sent, whether paid or not, or later written off; drafts
     * and cancelled invoices are left out). A foreign invoice converts at the exchange rate from its issue date;
     * one whose currency has no rate by then cannot be converted and is left out.
     */
    @Transactional(readOnly = true)
    public TaxSummaryResponse taxSummary(LocalDate from, LocalDate to) {
        if (from.isAfter(to)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The start date must not be after the end date");
        }
        List<InvoiceStatus> charged = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL, InvoiceStatus.PAID,
                InvoiceStatus.WRITTEN_OFF);
        String home = settings.homeCurrency();
        BigDecimal tax = BigDecimal.ZERO;
        BigDecimal levy = BigDecimal.ZERO;
        long count = 0;
        for (Invoice invoice : invoices.findByStatusInAndIssuedDateBetween(charged, from, to)) {
            String currency = invoice.getProject().getClient().getCurrency();
            if (currency.equals(home)) {
                tax = tax.add(invoice.getTax());
                levy = levy.add(invoice.getLevy());
                count++;
                continue;
            }
            var inHomeTax = fxRates.toHome(currency, invoice.getIssuedDate(), invoice.getTax());
            var inHomeLevy = fxRates.toHome(currency, invoice.getIssuedDate(), invoice.getLevy());
            if (inHomeTax.isPresent() && inHomeLevy.isPresent()) {
                tax = tax.add(inHomeTax.get());
                levy = levy.add(inHomeLevy.get());
                count++;
            }
        }
        tax = tax.setScale(2, RoundingMode.HALF_UP);
        levy = levy.setScale(2, RoundingMode.HALF_UP);
        return new TaxSummaryResponse(from, to, home, count, tax, levy, tax.add(levy));
    }
}
package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * The tax charged on invoices issued on or between two dates, in the home currency: the sales tax and the levy
 * (second tax) separately, and together as the total, with how many invoices they came from.
 */
public record TaxSummaryResponse(LocalDate from, LocalDate to, String homeCurrency, long invoices, BigDecimal tax,
        BigDecimal levy, BigDecimal total) {
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export interface TopClient {
  id: number;
  name: string;
  /** The client's currency; what they owe is in it. */
  currency: CurrencyCode;
  outstanding: number;
  /** What they owe converted into the home currency; the clients are ranked by it. */
  outstandingHome: number;
}

/** What is still owed in one currency; different currencies are never added together. */
export interface CurrencyTotal {
  currency: CurrencyCode;
  amount: number;
}

/** What is overdue, in the home currency, by how many days past due. */
export interface OverdueBuckets {
  days0To30: number;
  days31To60: number;
  days60Plus: number;
}

export interface DashboardSummary {
  clients: number;
  projects: number;
  /** What is still owed, one total per currency anything is owed in. */
  outstanding: CurrencyTotal[];
  /** Everything outstanding as one total in the home currency, each invoice converted at its issue date's rate. */
  outstandingHome: number;
  overdue: number;
  /** The currency the overdue amount is given in. */
  homeCurrency: CurrencyCode;
  /** What is left to pay on overdue invoices plus the late fees and instalment interest they have built up, in the home currency. */
  overdueAmount: number;
  /** The overdue amount split by how many days past due each invoice is. */
  overdueBuckets: OverdueBuckets;
  topClients: TopClient[];
}

/** The tax charged on invoices issued on or between two dates, in the home currency. */
export interface TaxSummary {
  from: string;
  to: string;
  homeCurrency: CurrencyCode;
  /** How many invoices the tax came from. */
  invoices: number;
  tax: number;
  /** The levy (second tax). */
  levy: number;
  /** The tax and levy together. */
  total: number;
}

@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly http = inject(HttpClient);

  summary(): Observable<DashboardSummary> {
    return this.http.get<DashboardSummary>('/api/dashboard');
  }

  taxSummary(from: string, to: string): Observable<TaxSummary> {
    return this.http.get<TaxSummary>('/api/dashboard/tax-summary', { params: new HttpParams().set('from', from).set('to', to) });
  }
}
import { Component, inject, signal } from '@angular/core';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService, DashboardSummary } from './dashboard.service';
import { TaxSummaryReport } from './tax-summary';
import { UpcomingRecurringInvoices } from './upcoming-recurring-invoices';

// Dashboard page: how many clients and projects there are, and the total still owed in each currency
// (what is left to pay on invoices that have been sent but not yet fully paid; drafts are not
// counted), plus one grand total of it in the home currency with each invoice converted at the
// exchange rate from its own issue date, and how many of those sent
// invoices are past their due date, with what is overdue on them (left to pay plus accrued late fees and
// instalment interest, in the home currency), also split by how many days overdue each invoice is. Also lists the top five clients ranked by what they still owe
// converted into the home currency, each shown in their own currency and in the home currency, and the recurring invoices coming up with when each falls. A tax summary for a chosen date range can be opened from here.
@Component({
  selector: 'app-dashboard',
  imports: [MoneyPipe, TaxSummaryReport, UpcomingRecurringInvoices],
  template: `
    <h1>Dashboard</h1>

    @if (loadError()) {
      <p role="alert" data-testid="dashboard-error">{{ loadError() }}</p>
    } @else if (summary(); as s) {
      <dl data-testid="dashboard-summary">
        <div>
          <dt>Clients</dt>
          <dd data-testid="dashboard-clients-count">{{ s.clients }}</dd>
        </div>
        <div>
          <dt>Jobs</dt>
          <dd data-testid="dashboard-projects-count">{{ s.projects }}</dd>
        </div>
        <div>
          <dt>Outstanding</dt>
          @for (t of s.outstanding; track t.currency) {
            <dd [attr.data-testid]="'dashboard-outstanding-' + t.currency">{{ t.amount | money: t.currency }}</dd>
          } @empty {
            <dd data-testid="dashboard-outstanding-none">Nothing owed</dd>
          }
        </div>
        <div>
          <dt>Outstanding in {{ s.homeCurrency }} (converted at each invoice's date)</dt>
          <dd data-testid="dashboard-outstanding-home">{{ s.outstandingHome | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue invoices</dt>
          <dd data-testid="dashboard-overdue-count">{{ s.overdue }}</dd>
        </div>
        <div>
          <dt>Overdue amount (including late fees and interest)</dt>
          <dd data-testid="dashboard-overdue-amount">{{ s.overdueAmount | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue up to 30 days</dt>
          <dd data-testid="dashboard-overdue-0-30">{{ s.overdueBuckets.days0To30 | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue 31 to 60 days</dt>
          <dd data-testid="dashboard-overdue-31-60">{{ s.overdueBuckets.days31To60 | money: s.homeCurrency }}</dd>
        </div>
        <div>
          <dt>Overdue more than 60 days</dt>
          <dd data-testid="dashboard-overdue-60-plus">{{ s.overdueBuckets.days60Plus | money: s.homeCurrency }}</dd>
        </div>
      </dl>

      <section data-testid="dashboard-top-clients" aria-labelledby="dashboard-top-clients-heading">
        <h2 id="dashboard-top-clients-heading">Top clients by amount owed (in {{ s.homeCurrency }})</h2>
        @if (s.topClients.length) {
          <ol>
            @for (c of s.topClients; track c.id) {
              <li [attr.data-testid]="'top-client-row-' + c.id">
                <span data-testid="top-client-name">{{ c.name }}</span>:
                <span data-testid="top-client-amount">{{ c.outstanding | money: c.currency }}</span>
                @if (c.currency !== s.homeCurrency) {
                  (<span data-testid="top-client-amount-home">{{ c.outstandingHome | money: s.homeCurrency }}</span>)
                }
              </li>
            }
          </ol>
        } @else {
          <p data-testid="dashboard-top-clients-empty">No clients owe anything.</p>
        }
      </section>
    } @else {
      <p data-testid="dashboard-loading">Loading…</p>
    }

    <app-upcoming-recurring-invoices />

    <button
      type="button"
      data-testid="tax-summary-open"
      aria-controls="tax-summary"
      [attr.aria-expanded]="taxSummaryOpen()"
      (click)="taxSummaryOpen.set(!taxSummaryOpen())"
    >
      {{ taxSummaryOpen() ? 'Hide tax summary' : 'Tax summary' }}
    </button>
    @if (taxSummaryOpen()) {
      <app-tax-summary id="tax-summary" />
    }
  `,
})
export class Dashboard {
  protected readonly summary = signal<DashboardSummary | null>(null);
  protected readonly loadError = signal<string | null>(null);
  protected readonly taxSummaryOpen = signal(false);

  constructor() {
    inject(DashboardService)
      .summary()
      .subscribe({
        next: (s) => this.summary.set(s),
        error: () => this.loadError.set('Could not load the dashboard. Please try again.'),
      });
  }
}
import { Component, inject, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService } from './dashboard.service';

// The total tax charged over a chosen date range: the sales tax and levy on invoices issued within it that were
// sent (drafts and cancelled invoices are left out), in the home currency.
@Component({
  selector: 'app-tax-summary',
  imports: [MoneyPipe],
  styles: `
    .tax-summary-range {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.5rem;
    }
    .tax-summary-figures {
      display: grid;
      grid-template-columns: max-content max-content;
      gap: 0.25rem 1.5rem;
    }
    .tax-summary-figures dd {
      margin: 0;
      text-align: right;
    }
  `,
  template: `
    <section aria-labelledby="tax-summary-heading" data-testid="tax-summary">
      <h2 id="tax-summary-heading">Tax summary</h2>
      <form class="tax-summary-range" (submit)="apply($event, fromInput.value, toInput.value)">
        <label for="tax-summary-from">From</label>
        <input #fromInput id="tax-summary-from" type="date" required data-testid="tax-summary-from" />
        <label for="tax-summary-to">To</label>
        <input #toInput id="tax-summary-to" type="date" required data-testid="tax-summary-to" />
        <button type="submit" data-testid="tax-summary-apply">Show tax</button>
      </form>
      @if (rangeError()) {
        <p role="alert" data-testid="tax-summary-range-error">{{ rangeError() }}</p>
      } @else if (summary.error()) {
        <p role="alert" data-testid="tax-summary-error">Could not load the tax summary.</p>
      } @else if (summary.value(); as t) {
        <dl class="tax-summary-figures" aria-live="polite">
          <dt>Invoices</dt>
          <dd data-testid="tax-summary-invoices">{{ t.invoices }}</dd>
          <dt>Sales tax</dt>
          <dd data-testid="tax-summary-tax">{{ t.tax | money: t.homeCurrency }}</dd>
          <dt>Levy</dt>
          <dd data-testid="tax-summary-levy">{{ t.levy | money: t.homeCurrency }}</dd>
          <dt>Total tax charged</dt>
          <dd data-testid="tax-summary-total">{{ t.total | money: t.homeCurrency }}</dd>
        </dl>
      }
    </section>
  `,
})
export class TaxSummaryReport {
  private readonly service = inject(DashboardService);

  private readonly range = signal<{ from: string; to: string } | undefined>(undefined);
  protected readonly rangeError = signal<string | null>(null);

  protected readonly summary = rxResource({
    params: () => this.range(),
    stream: ({ params }) => this.service.taxSummary(params.from, params.to),
  });

  protected apply(event: Event, from: string, to: string): void {
    event.preventDefault();
    if (!from || !to) {
      return;
    }
    if (from > to) {
      this.rangeError.set('The start date must not be after the end date.');
      return;
    }
    this.rangeError.set(null);
    this.range.set({ from, to });
  }
}
import { Component, inject } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { MoneyPipe } from '../currencies/money.pipe';
import { RecurringInvoiceService } from '../recurring/recurring-invoice.service';

// The recurring invoices across all projects that are coming up (next falling today or later), soonest first,
// each with the date it next falls on.
@Component({
  selector: 'app-upcoming-recurring-invoices',
  imports: [MoneyPipe, RouterLink],
  template: `
    <section aria-labelledby="upcoming-recurring-heading" data-testid="upcoming-recurring">
      <h2 id="upcoming-recurring-heading">Upcoming recurring invoices</h2>
      @if (upcoming.error()) {
        <p role="alert" data-testid="upcoming-recurring-error">Could not load the upcoming recurring invoices.</p>
      } @else if (upcoming.hasValue()) {
        @if (upcoming.value().length === 0) {
          <p data-testid="upcoming-recurring-empty">No recurring invoices coming up.</p>
        } @else {
          <table>
            <thead>
              <tr>
                <th scope="col">Next invoice</th>
                <th scope="col">Job</th>
                <th scope="col">Client</th>
                <th scope="col">Amount</th>
                <th scope="col">Repeats</th>
              </tr>
            </thead>
            <tbody>
