/** A scheduled part of an invoice: an amount due on a date. */
@Entity
@Table(name = "invoice_instalment")
public class Instalment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "invoice_id", nullable = false)
